import{_ as t,o,c as e,a4 as r}from"./chunks/framework.9tZL7ZIQ.js";const _=JSON.parse('{"title":"企业准则","description":"","frontmatter":{},"headers":[],"relativePath":"09_books/巴菲特之道/准则/01_企业准则.md","filePath":"09_books/巴菲特之道/准则/01_企业准则.md"}'),l={name:"09_books/巴菲特之道/准则/01_企业准则.md"};function i(n,a,s,h,p,c){return o(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="企业准则" tabindex="-1">企业准则 <a class="header-anchor" href="#企业准则" aria-label="Permalink to &quot;企业准则&quot;">​</a></h1><p>巴菲特在选择投资标的时，首先考察的是企业本身的质量。好的企业是投资的根基。</p><h2 id="三大企业准则" tabindex="-1">三大企业准则 <a class="header-anchor" href="#三大企业准则" aria-label="Permalink to &quot;三大企业准则&quot;">​</a></h2><h3 id="_1-简单易懂" tabindex="-1">1. 简单易懂 <a class="header-anchor" href="#_1-简单易懂" aria-label="Permalink to &quot;1. 简单易懂&quot;">​</a></h3><blockquote><p><strong>&quot;你必须能理解这家公司的业务。&quot;</strong></p></blockquote><p>巴菲特只投资于自己能够理解的公司。他avoid投资那些业务复杂、难以预测的公司。</p><p><strong>核心要点：</strong></p><ul><li>了解公司的产品或服务</li><li>理解公司的盈利模式</li><li>清楚公司如何赚钱</li></ul><p><strong>相关阅读：</strong> <a href="/02_concepts/circle-of-competence.html">能力圈</a> - 坚守自己的能力圈</p><hr><h3 id="_2-稳定业务" tabindex="-1">2. 稳定业务 <a class="header-anchor" href="#_2-稳定业务" aria-label="Permalink to &quot;2. 稳定业务&quot;">​</a></h3><blockquote><p><strong>&quot;我们想要的是持久的竞争力。&quot;</strong></p></blockquote><p>巴菲特偏好那些拥有稳定运营历史的公司。他avoid投资于初创公司或高度周期性的企业。</p><p><strong>核心要点：</strong></p><ul><li>至少10年以上的运营历史</li><li>稳定的盈利能力</li><li>可预测的现金流</li></ul><p><strong>相关阅读：</strong> <a href="/02_concepts/long-term.html">长期主义</a> - 时间的朋友的</p><hr><h3 id="_3-长期前景" tabindex="-1">3. 长期前景 <a class="header-anchor" href="#_3-长期前景" aria-label="Permalink to &quot;3. 长期前景&quot;">​</a></h3><blockquote><p><strong>&quot;护城河是最重要的。&quot;</strong></p></blockquote><p>这是企业准则中最关键的一条。公司必须拥有可持续的竞争优势，即&quot;经济护城河&quot;。</p><p><strong>核心要点：</strong></p><ul><li>无形资产（品牌、专利、特许经营权）</li><li>成本优势</li><li>网络效应</li><li>有效规模</li><li>转换成本</li></ul><p><strong>相关阅读：</strong> <a href="/02_concepts/moat.html">护城河</a></p><hr><h2 id="案例-可口可乐" tabindex="-1">案例：可口可乐 <a class="header-anchor" href="#案例-可口可乐" aria-label="Permalink to &quot;案例：可口可乐&quot;">​</a></h2><p>1988年巴菲特重仓买入可口可乐，正是基于这三大企业准则：</p><ul><li><strong>简单易懂</strong>：饮料业务一目了然</li><li><strong>稳定业务</strong>：百年老店，业绩稳定</li><li><strong>长期前景</strong>：强大的品牌护城河</li></ul><p><strong>相关阅读：</strong> <a href="/03_companies/可口可乐.html">可口可乐</a></p><hr><h2 id="与股东信的印证" tabindex="-1">与股东信的印证 <a class="header-anchor" href="#与股东信的印证" aria-label="Permalink to &quot;与股东信的印证&quot;">​</a></h2><p>巴菲特的四大类12条准则，可以在70年致股东信中找到大量印证：</p><ul><li>1989年：首次系统阐述<a href="/02_concepts/deferred-tax.html">递延税复利</a>优势</li><li>1983年：阐述<a href="/search.html?q=经济商誉vs会计商誉">经济商誉vs会计商誉</a></li><li>1981年：&quot;通胀绦虫&quot;比喻——<a href="/search.html?q=通胀">通胀</a>对企业的侵蚀</li></ul>',32)])])}const d=t(l,[["render",i]]);export{_ as __pageData,d as default};
